#!/usr/bin/env python3
import html,json,os
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__))); DATA=os.path.join(ROOT,'data'); OUT=os.path.join(ROOT,'docs','index.html')
def esc(v): return html.escape(str(v if v is not None else '-'))
def num(v,d=0):
    try:return float(v)
    except:return d
def pct(v): return f'{num(v):+.1f}%'
def cls(v): return 'up' if num(v)>=0 else 'down'
def load(name):
    try:
        with open(os.path.join(DATA,name),encoding='utf-8') as f:return json.load(f)
    except:return {}
def factors(r):
    m=[('辨识度',['identity_score','recognition_score']),('资金',['capital_score','fund_score']),('K线',['kline_score','technical_score']),('题材',['theme_score','topic_score']),('板块',['sector_score']),('流动性',['liquidity_score']),('情绪',['emotion_score','sentiment_score'])]
    a=[]
    for label,ks in m:
        for k in ks:
            if r.get(k) not in (None,''): a.append(f'<span class="factor"><b>{esc(label)}</b> {esc(r[k])}</span>');break
    return ''.join(a) or '<span class="factor muted">七因子明细未单独存储</span>'
def row(i,r):
    rec=r.get('recency') or {}; hist=r.get('history') or {}; res=r.get('resonance') or {}; w=r.get('next_day_watch') or []
    sector=r.get('sector') or r.get('sw_industry') or '-'; text='；'.join(map(str,w[:2])) if w else '-'
    return f'<tr><td>{i}</td><td class="stock"><b>{esc(r.get("name"))}</b><small>{esc(r.get("code"))} · {esc(sector)}</small></td><td>{esc(r.get("pool"))}</td><td>P{esc(rec.get("tier"))}</td><td><b>{num(r.get("adjusted_total")):.1f}</b><div class="factors">{factors(r)}</div></td><td class="{cls(r.get("change_pct"))}">{pct(r.get("change_pct"))}</td><td>{esc(r.get("turnover_rate"))}%</td><td>{esc(r.get("lianban_probability"))}%</td><td>{esc(hist.get("limit_up_count"))}</td><td>{esc(hist.get("days_since_last_lu"))}日</td><td>{esc(res.get("count",0))}/3</td><td class="watch-cell">{esc(text)}</td></tr>'
def news(items,empty):
    if not items:return f'<div class="empty">{esc(empty)}</div>'
    return ''.join(f'<div class="news"><b>{esc(x.get("title",""))}</b><small>{esc(x.get("pubDate",""))}</small></div>' for x in items[:8])

def main():
    d=load('seven_factor_latest.json'); e=load('evening_latest.json'); m=load('morning_latest.json'); c=list(d.get('candidates') or [])
    if not c: raise SystemExit('candidate pool empty')
    s=d.get('market_sentiment') or {}; ss=num(s.get('sentiment_score'),50)
    if ss<40: act,desc='谨慎观察','市场偏弱，等待确认，不因为高分个股强行出手。'
    elif ss<55: act,desc='轻仓试错','市场偏弱，优先等待主线与资金确认。'
    elif ss<70: act,desc='结构性参与','围绕强板块挑核心，重点观察池优先。'
    else: act,desc='积极参与','市场进攻条件较好，优先主线核心与首板前候选。'
    ordered=sorted(c,key=lambda r:(int(num((r.get('recency') or {}).get('tier'),99)),-num(r.get('adjusted_total')))); focus=[r for r in ordered if r.get('pool')=='重点观察'][:8]
    cards=[]
    for i,r in enumerate(focus,1):
        rec=r.get('recency') or {}; hist=r.get('history') or {}; res=r.get('resonance') or {}; w=r.get('next_day_watch') or ['等待信号确认']; n=int(num(res.get('count'),0))
        cards.append(f'<article class="focus"><div class="rank">TOP {i}</div><div class="fmain"><div><b>{esc(r.get("name"))}</b><small>{esc(r.get("code"))} · {esc(r.get("sector","未分类"))}</small></div><strong>{num(r.get("adjusted_total")):.1f}</strong><span class="pill">P{esc(rec.get("tier","-"))}</span></div><div class="fm"><span>三共振 <b class="gold">{"●"*n+"○"*max(0,3-n)}</b></span><span>连板概率 <b>{esc(r.get("lianban_probability"))}%</b></span><span>涨幅 <b class="{cls(r.get("change_pct"))}">{pct(r.get("change_pct"))}</b></span><span>换手 <b>{esc(r.get("turnover_rate"))}%</b></span><span>历史涨停 <b>{esc(hist.get("limit_up_count"))}</b></span><span>距上次 <b>{esc(hist.get("days_since_last_lu"))}日</b></span></div><div class="watch"><b>次日重点</b><span>{esc(w[0])}</span><span>{esc(w[1]) if len(w)>1 else '-'}</span></div></article>')
    secs=sorted(d.get('sector_rankings') or [],key=lambda x:num(x.get('avg_change')),reverse=True)[:6]; cons=sorted(d.get('concept_rankings') or [],key=lambda x:num(x.get('avg_change')),reverse=True)[:10]
    sec=''.join(f'<div class="sector"><b>{esc(x.get("name"))}</b><strong class="{cls(x.get("avg_change"))}">{pct(x.get("avg_change"))}</strong><small>{esc(x.get("limit_up_count"))}涨停 · {esc(x.get("strong_count"))}强势</small></div>' for x in secs)
    con=''.join(f'<span class="concept">#{esc(x.get("rank"))} {esc(x.get("name"))} <em class="{cls(x.get("avg_change"))}">{pct(x.get("avg_change"))}</em></span>' for x in cons)
    rows=''.join(row(i,r) for i,r in enumerate(c,1))
    css='''<style>:root{--bg:#0a0d12;--p:#121720;--p2:#171e28;--l:#283241;--t:#e8eef7;--m:#8792a4;--up:#ff6575;--down:#35d09a;--gold:#f5c85b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}.wrap{max-width:1560px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;gap:20px}.title{font-size:27px;font-weight:900}.muted,small,.meta{color:var(--m)}.meta{text-align:right;font-size:11px;line-height:1.8}section{background:var(--p);border:1px solid var(--l);border-radius:15px;padding:16px;margin-top:14px}.hero,.layout,.pipeline{display:grid;grid-template-columns:1.2fr 1fr;gap:14px}.hero .card,.pipeline-card{background:#111821;border:1px solid #263241;border-radius:12px;padding:18px}.action{font-size:29px;font-weight:900}.metrics,.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:12px}.metric,.stat{padding:10px;background:#10151d;border:1px solid #222c38;border-radius:9px}.metric span,.stat span{display:block;color:var(--m);font-size:10px}.metric b,.stat b{display:block;margin-top:4px;font-size:17px}.stat b{font-size:25px}.up{color:var(--up)}.down{color:var(--down)}.gold{color:var(--gold)}.focus-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.focus{background:var(--p2);border:1px solid var(--l);border-radius:12px;padding:13px}.rank{font-size:10px;color:var(--gold)}.fmain{display:grid;grid-template-columns:1fr 70px 42px;gap:8px;align-items:center;margin-top:5px}.fmain b{font-size:15px}.fmain small{display:block;font-size:9px;margin-top:3px}.fmain>strong{font-size:21px;text-align:right}.pill{display:inline-flex;padding:4px 7px;border-radius:6px;background:#202932;color:#c8d3e2;font-size:9px}.fm{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin:11px 0}.fm span{background:#10151d;border:1px solid #212b37;border-radius:7px;padding:7px;color:var(--m);font-size:9px}.fm b{display:block;color:var(--t);margin-top:3px}.watch{display:flex;gap:8px;background:#0f141b;border-radius:7px;padding:8px;font-size:10px}.watch span{color:var(--m)}.sector{display:grid;grid-template-columns:1fr 70px 130px;gap:8px;padding:9px 10px;background:#10151d;border:1px solid #212b37;border-radius:8px;margin-bottom:7px}.concepts{display:flex;flex-wrap:wrap;gap:7px}.concept{padding:8px 9px;background:#10151d;border:1px solid #212b37;border-radius:8px;font-size:10px}.concept em{font-style:normal;margin-left:6px}.news{padding:8px 0;border-bottom:1px solid #222b36}.news b{display:block;font-size:10px}.news small{font-size:9px}.empty{padding:18px;text-align:center;color:var(--m);background:#0f141b;border-radius:8px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.toolbar input,.toolbar select,.toolbar button{background:#0f141b;border:1px solid #273140;color:var(--t);padding:8px;border-radius:8px}.table-wrap{max-height:760px;overflow:auto;border:1px solid #222c38;border-radius:10px}.table{width:100%;min-width:1240px;border-collapse:collapse}.table th,.table td{padding:8px;border-bottom:1px solid #222b36;text-align:left;font-size:10px;vertical-align:top}.table th{color:var(--m);position:sticky;top:0;background:#111821}.stock small{display:block;margin-top:3px}.factors{display:flex;flex-wrap:wrap;gap:4px;margin-top:5px}.factor{padding:3px 5px;border-radius:5px;background:#0f141b;border:1px solid #222c38;color:var(--m);white-space:nowrap}.factor b{color:var(--t)}.watch-cell{max-width:240px;line-height:1.5}.footer{text-align:center;color:#5d6979;font-size:10px;padding:18px}@media(max-width:1000px){.hero,.layout,.pipeline{grid-template-columns:1fr}.focus-grid{grid-template-columns:1fr}.fm{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.wrap{padding:12px}.top{flex-direction:column}.meta{text-align:left}.metrics,.stats{grid-template-columns:1fr 1fr}.fm{grid-template-columns:1fr 1fr}.sector{grid-template-columns:1fr 60px}.sector small{display:none}}</style>'''
    js='''<script>function filterRows(){const q=(document.getElementById("q").value||"").toLowerCase(),p=document.getElementById("pool").value;for(const tr of document.getElementById("poolBody").rows){const t=tr.innerText.toLowerCase(),pt=tr.children[2].innerText;tr.style.display=(p==="全部"||pt===p)&&(!q||t.includes(q))?"":"none"}}function sortScore(){const b=document.getElementById("poolBody"),a=[...b.rows].sort((x,y)=>(parseFloat(y.children[4].innerText)||0)-(parseFloat(x.children[4].innerText)||0));a.forEach(r=>b.appendChild(r))}</script>'''
    out='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>七因子 · 决策仪表盘</title>'+css+'</head><body><div class="wrap">'
    out+='<div class="top"><div><div class="title">七因子 · 决策仪表盘</div><div class="muted">收盘选股 → 晚间预判 → 隔夜修正 → 竞价确认</div></div><div class="meta">扫描 '+esc(d.get('scan_date'))+' '+esc(d.get('scan_time'))+'<br>20:00：'+('已生成' if e else '尚未生成')+'<br>08:00：'+('已生成' if m else '尚未生成')+'</div></div>'
    out+=f'<section class="hero"><div class="card"><div class="muted">当前市场状态</div><div class="action">{esc(act)}</div><div class="muted">情绪分 {ss:.1f} · {esc(s.get("sentiment_label","正常"))}</div><p class="muted">{esc(desc)}</p><div class="metrics"><div class="metric"><span>涨停</span><b class="up">{esc(s.get("limit_up_count"))}</b></div><div class="metric"><span>跌停</span><b class="down">{esc(s.get("limit_down_count"))}</b></div><div class="metric"><span>最高连板</span><b>{esc(s.get("max_boards_est"))}</b></div><div class="metric"><span>炸板率</span><b>{esc(s.get("explosion_rate"))}%</b></div></div></div><div class="card stats"><div class="stat"><span>重点观察</span><b>{len(focus)}</b></div><div class="stat"><span>预备池</span><b>{sum(r.get("pool")=="预备池" for r in c)}</b></div><div class="stat"><span>观察池</span><b>{sum(r.get("pool")=="观察池" for r in c)}</b></div><div class="stat"><span>完整候选池</span><b>{len(c)}</b></div></div></section>'
    out+=f'<section><h2>① 明日重点观察</h2><p class="muted">先看重点池，再看完整候选池</p><div class="focus-grid>{"".join(cards)}</div></section>'
    out+=f'<section><h2>② 主线与板块</h2><div class="layout"><div>{sec}</div><div class="concepts">{con}</div></div></section>'
    out+='<section><h2>③ 晚间预判 / 隔夜修正</h2><div class="pipeline"><div class="pipeline-card"><h3>20:00 · 明日预判</h3>'+news(e.get('headlines') or [],'等待20:00晚间信息更新。')+'</div><div class="pipeline-card"><h3>08:00 · 隔夜修正</h3>'+news(m.get('overnight_headlines') or [],'等待08:00隔夜信息更新。')+'</div></div></section>'
    out+=f'<section><h2>④ 完整候选池 <span class="muted">{len(c)}只</span></h2><p class="muted">完整展示，不折叠；搜索和池筛选直接在当前页面完成。</p><div class="toolbar"><input id="q" oninput="filterRows()" placeholder="搜索股票 / 代码 / 行业"><select id="pool" onchange="filterRows()"><option>全部</option><option>重点观察</option><option>预备池</option><option>观察池</option><option>淘汰</option></select><button onclick="sortScore()">按调整分排序</button></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>股票 / 行业</th><th>池</th><th>P</th><th>调整分 / 七因子</th><th>涨幅</th><th>换手</th><th>连板概率</th><th>历史涨停</th><th>距上次</th><th>三共振</th><th>次日重点</th></tr></thead><tbody id="poolBody">{rows}</tbody></table></div></section><div class="footer">七因子决策系统 · 仅供研究参考，不构成投资建议</div></div>'+js+'</body></html>'
    os.makedirs(os.path.dirname(OUT),exist_ok=True)
    with open(OUT,'w',encoding='utf-8') as f:f.write(out)
if __name__=='__main__':main()
